def send_request(self, data, path, method='POST'):
    headers = {'Content-Type': 'application/json'}
    try:
        response, content = self.connection.send(path, data, method=method, headers=headers)
    except HTTPError as exc:
        return exc.code, exc.read()
    return handle_response(content)   # e.g. JSON text -> dict
